@Test
void restartLoadsOnlyBoundedAllowListedRecords() {
    var path = directory.resolve("restart.ndjson");
    var first = new RetentionLog(path, Duration.ofDays(14), 2);
    first.append(new RetentionLog.Entry("one", NOW, "host.ready", Map.of("status", "ready")));
    first.append(new RetentionLog.Entry("two", NOW.plusSeconds(1), "host.ready", Map.of("status", "ready")));
    first.append(new RetentionLog.Entry("three", NOW.plusSeconds(2), "host.ready", Map.of("status", "ready")));

    var reopened = new RetentionLog(path, Duration.ofDays(14), 2);

    assertEquals(java.util.List.of("two", "three"),
            reopened.entries().stream().map(RetentionLog.Entry::id).toList());
}

